#!/usr/bin/env python3
"""Generate Bazel BUILD files for Kain Rust workspace packages.

Cargo.toml remains the source of truth. This script emits small direct
rules_rust BUILD files that consume crate_universe dependency macros.
"""

from __future__ import annotations

import argparse
import json
import os
import subprocess
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable


REPO_ROOT = Path(__file__).resolve().parents[2]
HEADER = """# @generated by tools/bazel/sync_rust_builds.py
# Do not edit by hand; update Cargo.toml and rerun the generator.
"""
COMMON_DATA_GLOBS = [
    "src/**/*",
    "tests/**/*",
    "examples/**/*",
    "benches/**/*",
    "commands/**/*",
    "data/**/*",
    "templates/**/*",
    "vendor/**/*",
    "generated/**/*",
]
FORCE_DIRECT_LIBRARY_PACKAGES = {"cli"}
FORCE_DIRECT_BINARY_TARGETS = {
    ("cli", "blade"),
    ("cli", "kain"),
    ("cli", "kn"),
}


@dataclass(frozen=True)
class RustTarget:
    name: str
    kind: list[str]
    crate_types: list[str]
    src_path: Path
    edition: str


@dataclass(frozen=True)
class Dependency:
    name: str
    kind: str | None
    path: Path | None
    optional: bool
    uses_default_features: bool
    features: list[str]


@dataclass(frozen=True)
class Package:
    name: str
    version: str
    manifest_path: Path
    targets: list[RustTarget]
    dependencies: list[Dependency]
    features: dict[str, list[str]]

    @property
    def directory(self) -> Path:
        return self.manifest_path.parent

    @property
    def default_features(self) -> list[str]:
        defaults = self.features.get("default", [])
        return [
            feature
            for feature in defaults
            if "/" not in feature and not feature.startswith("dep:")
        ]


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check",
        action="store_true",
        help="fail if generated BUILD files are missing or stale",
    )
    args = parser.parse_args()

    packages = load_workspace_packages()
    workspace_labels = workspace_package_labels(packages)
    workspace_features = workspace_package_features(packages)
    proc_macro_packages = {
        package.name
        for package in packages
        if any("proc-macro" in target.crate_types for target in package.targets)
    }
    stale = []
    rendered_outputs = {}
    for package in packages:
        rendered_outputs.update(
            render_package_build_outputs(
                package,
                workspace_labels,
                workspace_features,
                proc_macro_packages,
            )
        )
    for build_path, content in rendered_outputs.items():
        if args.check:
            existing = build_path.read_text(encoding="utf-8") if build_path.exists() else None
            if existing != content:
                stale.append(build_path)
        else:
            build_path.parent.mkdir(parents=True, exist_ok=True)
            build_path.write_text(content, encoding="utf-8")

    if stale:
        for path in stale:
            print(f"stale: {path.relative_to(REPO_ROOT)}", file=sys.stderr)
        print("Run: python tools/bazel/sync_rust_builds.py", file=sys.stderr)
        return 1

    verb = "checked" if args.check else "generated"
    print(f"{verb} {len(rendered_outputs)} Rust BUILD files")
    return 0


def load_workspace_packages() -> list[Package]:
    metadata = subprocess.check_output(
        ["cargo", "metadata", "--format-version", "1", "--no-deps"],
        cwd=REPO_ROOT,
        text=True,
    )
    decoded = json.loads(metadata)
    members = set(decoded["workspace_members"])
    packages = []
    for raw_package in decoded["packages"]:
        if raw_package["id"] not in members:
            continue
        packages.append(
            Package(
                name=raw_package["name"],
                version=raw_package["version"],
                manifest_path=Path(raw_package["manifest_path"]).resolve(),
                targets=[
                    RustTarget(
                        name=target["name"],
                        kind=target["kind"],
                        crate_types=target["crate_types"],
                        src_path=Path(target["src_path"]).resolve(),
                        edition=target["edition"],
                    )
                    for target in raw_package["targets"]
                ],
                dependencies=[
                    Dependency(
                        name=dependency["name"],
                        kind=dependency["kind"],
                        path=Path(dependency["path"]).resolve()
                        if dependency.get("path")
                        else None,
                        optional=dependency["optional"],
                        uses_default_features=dependency["uses_default_features"],
                        features=dependency.get("features", []),
                    )
                    for dependency in raw_package["dependencies"]
                ],
                features=raw_package.get("features", {}),
            )
        )
    return sorted(packages, key=lambda package: package.manifest_path.as_posix().lower())


def workspace_package_labels(packages: list[Package]) -> dict[Path, str]:
    return {
        package.directory: f"//{package.directory.relative_to(REPO_ROOT).as_posix()}:{package.name}"
        for package in packages
    }


def workspace_package_features(packages: list[Package]) -> dict[Path, list[str]]:
    packages_by_directory = {package.directory: package for package in packages}
    features_by_directory = {
        package.directory: set(package.default_features)
        for package in packages
    }

    for package in packages:
        for dependency in package.dependencies:
            if dependency.path not in packages_by_directory:
                continue
            dependency_package = packages_by_directory[dependency.path]
            enabled = features_by_directory[dependency.path]
            if dependency.uses_default_features:
                enabled.update(dependency_package.default_features)
            enabled.update(feature for feature in dependency.features if "/" not in feature)

    return {
        directory: sorted(resolve_feature_closure(packages_by_directory[directory], features))
        for directory, features in features_by_directory.items()
    }


def resolve_feature_closure(package: Package, initial_features: Iterable[str]) -> set[str]:
    resolved = set()
    pending = list(initial_features)
    optional_dependencies = {
        dependency.name
        for dependency in package.dependencies
        if dependency.optional
    }

    while pending:
        feature = pending.pop()
        if feature in resolved or "/" in feature or feature.startswith("dep:"):
            continue
        resolved.add(feature)
        if feature in optional_dependencies:
            continue
        pending.extend(package.features.get(feature, []))

    return resolved


def render_build_file(
    package: Package,
    workspace_labels: dict[Path, str],
    workspace_features: dict[Path, list[str]],
    proc_macro_packages: set[str],
) -> str:
    targets = []
    loads = [
        'load("@crates//:defs.bzl", "aliases", "all_crate_deps")',
        'load("@rules_rust//rust:defs.bzl", "rust_binary", "rust_library", "rust_proc_macro", "rust_test")',
    ]

    has_build_script = any("custom-build" in target.kind for target in package.targets)
    if has_build_script:
        loads.append('load("@rules_rust//cargo:defs.bzl", "cargo_build_script")')
        targets.append(render_build_script(package, workspace_labels, proc_macro_packages))

    for target in package.targets:
        if "custom-build" in target.kind:
            continue
        if is_library_target(target):
            targets.append(
                render_library(
                    package,
                    target,
                    has_build_script,
                    workspace_labels,
                    workspace_features,
                    proc_macro_packages,
                )
            )
        elif "bin" in target.kind:
            targets.append(
                render_binary(
                    package,
                    target,
                    has_build_script,
                    workspace_labels,
                    workspace_features,
                    proc_macro_packages,
                )
            )
        elif "test" in target.kind:
            targets.append(
                render_integration_test(
                    package,
                    target,
                    has_build_script,
                    workspace_labels,
                    workspace_features,
                    proc_macro_packages,
                )
            )

    lines = [HEADER.rstrip(), ""]
    lines.extend(loads)
    lines.extend(
        [
            "",
            'package(default_visibility = ["//visibility:public"])',
            "",
            "COMMON_COMPILE_DATA = glob(",
            format_string_list(COMMON_DATA_GLOBS, indent=4) + ",",
            '    exclude = ["**/*.rs"],',
            "    allow_empty = True,",
            ")",
            "",
        ]
    )
    lines.extend(targets)
    return "\n".join(lines).rstrip() + "\n"


def render_package_build_outputs(
    package: Package,
    workspace_labels: dict[Path, str],
    workspace_features: dict[Path, list[str]],
    proc_macro_packages: set[str],
) -> dict[Path, str]:
    return {
        package.directory / "BUILD.bazel": render_build_file(
            package,
            workspace_labels,
            workspace_features,
            proc_macro_packages,
        )
    }


def render_build_script(
    package: Package,
    workspace_labels: dict[Path, str],
    proc_macro_packages: set[str],
) -> str:
    return render_rule(
        "cargo_build_script",
        {
            "name": string_literal("build_script"),
            "srcs": ["build.rs"],
            "edition": string_literal(package.targets[0].edition),
            "aliases": "aliases(build = True, build_proc_macro = True)",
            "deps": deps_expression(
                internal_deps(package, workspace_labels, proc_macro_packages, {"build"}, False),
                "all_crate_deps(build = True)",
            ),
            "proc_macro_deps": deps_expression(
                internal_deps(package, workspace_labels, proc_macro_packages, {"build"}, True),
                "all_crate_deps(build_proc_macro = True)",
            ),
            "data": "COMMON_COMPILE_DATA",
            "pkg_name": string_literal(package.name),
        },
    )


def render_library(
    package: Package,
    target: RustTarget,
    has_build_script: bool,
    workspace_labels: dict[Path, str],
    workspace_features: dict[Path, list[str]],
    proc_macro_packages: set[str],
) -> str:
    rule = "rust_proc_macro" if "proc-macro" in target.crate_types else "rust_library"
    local_deps = internal_deps(package, workspace_labels, proc_macro_packages, {None}, False)
    if has_build_script:
        local_deps = [":build_script"] + local_deps
    deps = deps_expression(local_deps, "all_crate_deps(normal = True)")
    attrs = {
        "name": string_literal(package.name),
        "crate_name": string_literal(target.name),
        "crate_root": relpath(target.src_path, package.directory),
        "srcs": 'glob(["src/**/*.rs"])',
        "edition": string_literal(target.edition),
        "crate_features": workspace_features[package.directory],
        "aliases": "aliases()",
        "deps": deps,
        "proc_macro_deps": deps_expression(
            internal_deps(package, workspace_labels, proc_macro_packages, {None}, True),
            "all_crate_deps(proc_macro = True)",
        ),
        "compile_data": "COMMON_COMPILE_DATA",
    }
    if rule == "rust_library" and package.name in FORCE_DIRECT_LIBRARY_PACKAGES:
        attrs["force_all_deps_direct"] = "True"
    rendered = render_rule(rule, attrs)
    if "proc-macro" not in target.crate_types:
        rendered += render_unit_test(
            package,
            has_build_script,
            workspace_labels,
            workspace_features,
            proc_macro_packages,
        )
    return rendered


def render_unit_test(
    package: Package,
    has_build_script: bool,
    workspace_labels: dict[Path, str],
    workspace_features: dict[Path, list[str]],
    proc_macro_packages: set[str],
) -> str:
    local_deps = internal_deps(package, workspace_labels, proc_macro_packages, {"dev"}, False)
    if has_build_script:
        local_deps = [":build_script"] + local_deps
    deps = deps_expression(local_deps, "all_crate_deps(normal_dev = True)")
    return render_rule(
        "rust_test",
        {
            "name": string_literal("unit_test"),
            "crate": string_literal(f":{package.name}"),
            "edition": string_literal(package.targets[0].edition),
            "crate_features": workspace_features[package.directory],
            "aliases": "aliases(normal_dev = True, proc_macro_dev = True)",
            "deps": deps,
            "proc_macro_deps": deps_expression(
                internal_deps(package, workspace_labels, proc_macro_packages, {"dev"}, True),
                "all_crate_deps(proc_macro_dev = True)",
            ),
            "compile_data": "COMMON_COMPILE_DATA",
        },
    )


def render_binary(
    package: Package,
    target: RustTarget,
    has_build_script: bool,
    workspace_labels: dict[Path, str],
    workspace_features: dict[Path, list[str]],
    proc_macro_packages: set[str],
) -> str:
    name = target.name
    if (
        any(is_library_target(candidate) and candidate.name == target.name for candidate in package.targets)
        or target_name_collides_with_dependency_crate(package, target)
    ):
        name = f"{name}_bin"
    local_deps = internal_deps(package, workspace_labels, proc_macro_packages, {None}, False)
    package_lib_dep = package_library_dep(package)
    if package_lib_dep:
        local_deps = [package_lib_dep] + local_deps
    if has_build_script:
        local_deps = [":build_script"] + local_deps
    deps = deps_expression(local_deps, "all_crate_deps(normal = True)")
    attrs = {
        "name": string_literal(name),
        "crate_name": string_literal(target.name),
        "crate_root": relpath(target.src_path, package.directory),
        "srcs": 'glob(["src/**/*.rs"])',
        "edition": string_literal(target.edition),
        "crate_features": workspace_features[package.directory],
        "aliases": "aliases()",
        "deps": deps,
        "proc_macro_deps": deps_expression(
            internal_deps(package, workspace_labels, proc_macro_packages, {None}, True),
            "all_crate_deps(proc_macro = True)",
        ),
        "compile_data": "COMMON_COMPILE_DATA",
    }
    if (package.name, target.name) in FORCE_DIRECT_BINARY_TARGETS:
        attrs["force_all_deps_direct"] = "True"
    rendered = render_rule("rust_binary", attrs)
    if name != target.name:
        rendered += render_rule(
            "alias",
            {
                "name": string_literal(target.name),
                "actual": string_literal(f":{name}"),
            },
        )
    return rendered


def render_integration_test(
    package: Package,
    target: RustTarget,
    has_build_script: bool,
    workspace_labels: dict[Path, str],
    workspace_features: dict[Path, list[str]],
    proc_macro_packages: set[str],
) -> str:
    local_deps = internal_deps(
        package,
        workspace_labels,
        proc_macro_packages,
        {None, "dev"},
        False,
    )
    package_lib_dep = package_library_dep(package)
    if package_lib_dep:
        local_deps = [package_lib_dep] + local_deps
    if has_build_script:
        local_deps = [":build_script"] + local_deps
    deps = deps_expression(local_deps, "all_crate_deps(normal = True, normal_dev = True)")
    attrs = {
        "name": string_literal(f"{target.name}_test"),
        "crate_name": string_literal(target.name),
        "crate_root": relpath(target.src_path, package.directory),
        "srcs": 'glob(["src/**/*.rs", "tests/**/*.rs"])',
        "edition": string_literal(target.edition),
        "crate_features": workspace_features[package.directory],
        "aliases": "aliases(normal = True, normal_dev = True, proc_macro = True, proc_macro_dev = True)",
        "deps": deps,
        "proc_macro_deps": deps_expression(
            internal_deps(
                package,
                workspace_labels,
                proc_macro_packages,
                {None, "dev"},
                True,
            ),
            "all_crate_deps(proc_macro = True, proc_macro_dev = True)",
        ),
        "compile_data": "COMMON_COMPILE_DATA",
        "tags": ["manual"],
    }
    return render_rule("rust_test", attrs)


def internal_deps(
    package: Package,
    workspace_labels: dict[Path, str],
    proc_macro_packages: set[str],
    kinds: set[str | None],
    proc_macro: bool,
) -> list[str]:
    labels = []
    for dependency in package.dependencies:
        if dependency.kind not in kinds or dependency.path is None:
            continue
        label = workspace_labels.get(dependency.path)
        if not label:
            continue
        is_proc_macro = dependency.name in proc_macro_packages
        if is_proc_macro != proc_macro:
            continue
        labels.append(label)
    return sorted(set(labels))


def is_library_target(target: RustTarget) -> bool:
    return any(
        kind in {"lib", "rlib", "dylib", "cdylib", "staticlib", "proc-macro"}
        for kind in target.kind
    )


def package_library_dep(package: Package) -> str | None:
    for target in package.targets:
        if is_library_target(target) and "proc-macro" not in target.crate_types:
            return f":{package.name}"
    return None


def target_name_collides_with_dependency_crate(package: Package, target: RustTarget) -> bool:
    target_crate_name = target.name.replace("-", "_")
    dependency_crate_names = {
        dependency.name.replace("-", "_")
        for dependency in package.dependencies
        if dependency.kind is None
    }
    return target_crate_name in dependency_crate_names


def deps_expression(labels: list[str], external_expression: str) -> str:
    if not labels:
        return external_expression
    return f"{format_string_list(labels, indent=4)} + {external_expression}"


def render_rule(rule_name: str, attrs: dict[str, object]) -> str:
    lines = [f"{rule_name}("]
    for key, value in attrs.items():
        if value in (None, [], ""):
            continue
        lines.extend(format_attr(key, value))
    lines.append(")")
    lines.append("")
    return "\n".join(lines)


def format_attr(key: str, value: object) -> list[str]:
    if isinstance(value, list):
        if not value:
            return []
        return [f"    {key} = {format_string_list(value, indent=4)},"]
    return [f"    {key} = {value},"]


def format_string_list(values: Iterable[str], indent: int) -> str:
    values = list(values)
    if not values:
        return "[]"
    pad = " " * indent
    inner = "\n".join(f"{pad}    {string_literal(value)}," for value in values)
    return f"[\n{inner}\n{pad}]"


def relpath(path: Path, start: Path) -> str:
    relative = os.path.relpath(path, start)
    return string_literal(relative.replace(os.sep, "/"))


def string_literal(value: str) -> str:
    return json.dumps(value)


if __name__ == "__main__":
    raise SystemExit(main())
